WITH base AS (SELECT id, customer_id, account_type, opened_date, status, LOWER(account_type) AS account_type_lower FROM accounts WHERE status IN ('OPEN', 'FROZEN')) SELECT id, customer_id, account_type, status, FIRST_VALUE(status, TRUE) OVER w_ordered AS first_known_status, FIRST_VALUE(status) IGNORE NULLS OVER (PARTITION BY status ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_status_2, ROW_NUMBER() OVER w_part AS row_seq FROM base WINDOW w_ordered AS (ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY status ORDER BY opened_date DESC, id ASC);
